# --- 런타임 예외 ---

@Transactional
public void runtimeException() {
    repository.save(item);
    throw new RuntimeException();
}

#   Getting transaction for [...runtimeException]
#   Creating new transaction
#   Hibernate: insert into item (item_name,price,quantity) values (?,?,?)
#   Completing transaction for [...runtimeException] after exception:
#     java.lang.RuntimeException
#   Initiating transaction rollback
#   Rolling back JDBC transaction on Connection [conn0]

select count(*) from item;
#   -> 0

# --- 체크 예외 ---

@Transactional
public void checkedException() throws MyException {
    repository.save(item);
    throw new MyException();
}

#   Getting transaction for [...checkedException]
#   Creating new transaction
#   Hibernate: insert into item (item_name,price,quantity) values (?,?,?)
#   Completing transaction for [...checkedException] after exception:
#     hello.springtx.exception.MyException
#   Initiating transaction commit
#   Committing JDBC transaction on Connection [conn0]

select count(*) from item;
#   -> 1

#   예외가 났는데 저장됐다

# 두 로그의 차이는 한 단어다
#   Initiating transaction rollback
#   Initiating transaction commit

# --- Error ---

#   Completing transaction after exception: java.lang.OutOfMemoryError
#   Initiating transaction rollback

# --- 예외를 잡으면 ---

@Transactional
public void 잡는다() {
    repository.save(item);
    try {
        throw new RuntimeException();
    } catch (RuntimeException e) {
        log.error("handled");
    }
}

#   Hibernate: insert into item ...
#   handled
#   Completing transaction for [...잡는다]
#   Initiating transaction commit

#   'after exception' 이 없다. 프록시는 예외를 못 봤다.

# --- setRollbackOnly ---

#   } catch (RuntimeException e) {
#       TransactionAspectSupport.currentTransactionStatus()
#           .setRollbackOnly();
#   }

#   Hibernate: insert into item ...
#   Completing transaction for [...잡는다]
#   Global transaction is marked as rollback-only
#     but transactional code requested commit
#   Initiating transaction rollback

#   롤백됐다
